def transform(grid):
    g = np.array(grid)
    H, W = g.shape
    bg = background(g)
    objs = objects(g, bg=bg)

    def is_rect(o):
        y0, x0, y1, x1 = o["box"]
        return o["size"] == (y1 - y0 + 1) * (x1 - x0 + 1)

    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    choice = None
    for P in objs:
        if not is_rect(P):
            continue
        py0, px0, py1, px1 = P["box"]
        for dy, dx in dirs:
            # find first object hit along direction within P's perpendicular span
            best = None
            for T in objs:
                if T is P:
                    continue
                ty0, tx0, ty1, tx1 = T["box"]
                if dy != 0:
                    if tx1 < px0 or tx0 > px1:
                        continue
                    dist = (py0 - ty1) if dy < 0 else (ty0 - py1)
                else:
                    if ty1 < py0 or ty0 > py1:
                        continue
                    dist = (px0 - tx1) if dx < 0 else (tx0 - px1)
                if dist <= 0:
                    continue
                if best is None or dist < best[0]:
                    best = (dist, T)
            if best is None:
                continue
            T = best[1]
            if not is_rect(T):
                continue
            ty0, tx0, ty1, tx1 = T["box"]
            if dy != 0:
                a0, a1, b0, b1 = px0, px1, tx0, tx1
            else:
                a0, a1, b0, b1 = py0, py1, ty0, ty1
            if b0 < a0 and b1 > a1 and (a0 - b0) == (b1 - a1):
                choice = (P, T, dy, dx)
                break
        if choice:
            break

    out = g.copy()
    if choice is None:
        emit(out, "No projectile/target pair found; grid unchanged.")
        return out
    P, T, dy, dx = choice
    py0, px0, py1, px1 = P["box"]
    ty0, tx0, ty1, tx1 = T["box"]

    # 1. remove projectile
    for (y, x) in P["cells"]:
        out[y, x] = bg
    emit(out, "Lift the projectile block off the grid.")

    # 2. split target
    for (y, x) in T["cells"]:
        out[y, x] = bg
    if dy != 0:
        w = px1 - px0 + 1
        s = w // 2
        mid2 = tx0 + tx1  # compare 2x vs mid2
        for (y, x) in T["cells"]:
            nx = x - s if 2 * x < mid2 else x + s
            if 0 <= nx < W:
                out[y, nx] = T["colour"]
    else:
        h = py1 - py0 + 1
        s = h // 2
        mid2 = ty0 + ty1
        for (y, x) in T["cells"]:
            ny = y - s if 2 * y < mid2 else y + s
            if 0 <= ny < H:
                out[ny, x] = T["colour"]
    emit(out, "Split the target rectangle at its centre, pushing each half outward by half the projectile width.")

    # 3. place projectile at grid edge
    ph, pw = py1 - py0 + 1, px1 - px0 + 1
    if dy < 0:
        oy, ox = 0, px0
    elif dy > 0:
        oy, ox = H - ph, px0
    elif dx < 0:
        oy, ox = py0, 0
    else:
        oy, ox = py0, W - pw
    for (y, x) in P["cells"]:
        out[y - py0 + oy, x - px0 + ox] = P["colour"]
    emit(out, "The projectile flies through the gap and stops at the grid edge.")
    return out
